    @ParameterizedTest
    @MethodSource("furthestMonthOracles")
    void furthestMonthOracles(List<Integer> costDeltas, int spendBudget, int waiverCredits, int expected) {
        assertEquals(expected, CapacityPlannerService.furthestMonth(costDeltas, spendBudget, waiverCredits));
    }

    @ParameterizedTest
    @MethodSource("moreFurthestMonthOracles")
    void furthestMonthExtendedOracles(List<Integer> costDeltas, int spendBudget, int waiverCredits, int expected) {
        assertEquals(expected, CapacityPlannerService.furthestMonth(costDeltas, spendBudget, waiverCredits));
    }

    private static boolean reachable(List<Integer> prefix, int spendBudget, int waiverCredits) {
        for (int mask = 0; mask < 1 << prefix.size(); mask++) {
            int waived = 0;
            int spent = 0;
            for (int i = 0; i < prefix.size(); i++) {
                if ((mask & (1 << i)) != 0) {
                    waived++;
                } else {
                    spent += Math.max(prefix.get(i), 0);
                }
            }
            if (waived <= waiverCredits && spent <= spendBudget) {
                return true;
            }
        }
        return false;
    }

    private static int referenceFurthestMonth(List<Integer> costDeltas, int spendBudget, int waiverCredits) {
        int length = 0;
        while (length < costDeltas.size() && reachable(costDeltas.subList(0, length + 1), spendBudget, waiverCredits)) {
            length++;
        }
        return length;
    }

    @Test
    void matchesAnExhaustiveSubsetSearchForEverySmallInput() {
        int[] values = {-1, 0, 1, 2, 3};
        List<List<Integer>> inputs = new ArrayList<>();
        inputs.add(List.of());
        int previousStart = 0;
        for (int length = 1; length <= 5; length++) {
            int previousEnd = inputs.size();
            for (int p = previousStart; p < previousEnd; p++) {
                for (int value : values) {
                    List<Integer> next = new ArrayList<>(inputs.get(p));
                    next.add(value);
                    inputs.add(next);
                }
            }
            previousStart = previousEnd;
        }
        for (List<Integer> costDeltas : inputs) {
            for (int spendBudget = 0; spendBudget <= 6; spendBudget++) {
                for (int waiverCredits = 0; waiverCredits <= 3; waiverCredits++) {
                    assertEquals(referenceFurthestMonth(costDeltas, spendBudget, waiverCredits),
                            CapacityPlannerService.furthestMonth(costDeltas, spendBudget, waiverCredits),
                            costDeltas + " budget=" + spendBudget + " credits=" + waiverCredits);
                }
            }
        }
    }

    @Test
    void neverMutatesTheInputArray() {
        List<Integer> costDeltas = new ArrayList<>(List.of(4, 2, 7, 6, 9, 14, 12));
        CapacityPlannerService.furthestMonth(costDeltas, 5, 1);
        assertEquals(List.of(4, 2, 7, 6, 9, 14, 12), costDeltas);
    }

    @Test
    void moreBudgetOrMoreWaiversNeverReachAShorterMonth() {
        List<Integer> costDeltas = List.of(4, 12, 2, 7, 3, 18, 20, 3, 19);
        for (int waivers = 0; waivers <= 4; waivers++) {
            int previous = -1;
            for (int budget = 0; budget <= 60; budget++) {
                int month = CapacityPlannerService.furthestMonth(costDeltas, budget, waivers);
                assertTrue(month >= previous, "budget=" + budget + " waivers=" + waivers);
                previous = month;
            }
        }
        for (int budget = 0; budget <= 60; budget += 5) {
            int previous = -1;
            for (int waivers = 0; waivers <= 9; waivers++) {
                int month = CapacityPlannerService.furthestMonth(costDeltas, budget, waivers);
                assertTrue(month >= previous, "budget=" + budget + " waivers=" + waivers);
                previous = month;
            }
        }
    }

    @Test
    void enoughWaiversAlwaysReachTheEnd() {
        List<Integer> costDeltas = List.of(5, 9, 1, 20, 3, 8);
        assertEquals(costDeltas.size(), CapacityPlannerService.furthestMonth(costDeltas, 0, costDeltas.size()));
    }
